from config import merge_config


def test_existing_contract():
    assert merge_config({"a": 1}, {"a": 2, "b": 3}) == {"a": 2, "b": 3}
    assert merge_config({}, {}) == {}


def test_recursive_merge_overrides_win_at_leaves():
    defaults = {"a": {"b": 1, "c": 2}, "d": 3}
    overrides = {"a": {"b": 10}}
    assert merge_config(defaults, overrides) == {"a": {"b": 10, "c": 2}, "d": 3}


def test_deeply_nested_merge():
    defaults = {"a": {"b": {"c": 1, "d": 2}}}
    overrides = {"a": {"b": {"c": 9}}}
    assert merge_config(defaults, overrides) == {"a": {"b": {"c": 9, "d": 2}}}


def test_lists_are_replaced_not_concatenated():
    defaults = {"a": [1, 2, 3]}
    overrides = {"a": [4]}
    assert merge_config(defaults, overrides) == {"a": [4]}


def test_nested_lists_are_replaced():
    defaults = {"a": {"b": [1, 2]}}
    overrides = {"a": {"b": [3, 4]}}
    assert merge_config(defaults, overrides) == {"a": {"b": [3, 4]}}


def test_inputs_are_not_mutated():
    defaults = {"a": {"b": 1}, "c": [1, 2]}
    overrides = {"a": {"b": 2}, "c": [3]}
    defaults_snapshot = {"a": {"b": 1}, "c": [1, 2]}
    overrides_snapshot = {"a": {"b": 2}, "c": [3]}
    merge_config(defaults, overrides)
    assert defaults == defaults_snapshot
    assert overrides == overrides_snapshot


def test_result_does_not_share_nested_objects_with_inputs():
    defaults = {"a": {"b": 1}, "c": [1, 2]}
    overrides = {"a": {"b": 2}, "c": [3]}
    result = merge_config(defaults, overrides)
    assert result["a"] is not defaults["a"]
    assert result["a"] is not overrides["a"]
    assert result["c"] is not defaults["c"]
    assert result["c"] is not overrides["c"]


def test_mutating_result_does_not_affect_inputs():
    defaults = {"a": {"b": 1}, "c": [1, 2]}
    overrides = {"a": {"b": 2}, "c": [3]}
    result = merge_config(defaults, overrides)
    result["a"]["b"] = 99
    result["c"].append(4)
    assert defaults == {"a": {"b": 1}, "c": [1, 2]}
    assert overrides == {"a": {"b": 2}, "c": [3]}


def test_override_mapping_replaces_non_mapping_default():
    defaults = {"a": 1}
    overrides = {"a": {"b": 2}}
    assert merge_config(defaults, overrides) == {"a": {"b": 2}}


def test_override_non_mapping_replaces_mapping_default():
    defaults = {"a": {"b": 2}}
    overrides = {"a": 1}
    assert merge_config(defaults, overrides) == {"a": 1}


def test_new_keys_from_overrides_are_copied():
    defaults = {}
    overrides = {"a": {"b": 1}, "c": [1, 2]}
    result = merge_config(defaults, overrides)
    assert result == {"a": {"b": 1}, "c": [1, 2]}
    assert result["a"] is not overrides["a"]
    assert result["c"] is not overrides["c"]


def test_result_types_are_dicts():
    result = merge_config({"a": {"b": 1}}, {"a": {"c": 2}})
    assert isinstance(result, dict)
    assert isinstance(result["a"], dict)
    assert isinstance(merge_config({"a": [1]}, {"a": [2]})["a"], list)

from collections.abc import Mapping


def merge_config(defaults, overrides):
    result = {}
    for key, value in defaults.items():
        if isinstance(value, Mapping):
            result[key] = merge_config(value, {})
        else:
            result[key] = value
    for key, value in overrides.items():
        if (
            key in result
            and isinstance(result[key], Mapping)
            and isinstance(value, Mapping)
        ):
            result[key] = merge_config(result[key], value)
        elif isinstance(value, Mapping):
            result[key] = merge_config(value, {})
        else:
            result[key] = value
    return result
